import { fromEvent } from 'rxjs';
import { debounceTime, switchMap } from 'rxjs/operators';

searchInput$ = fromEvent(this.input.nativeElement, 'input').pipe(
  debounceTime(300),
  map((event: any) => event.target.value),
  switchMap(term => this.http.get(`/api/search?q=${term}`))
);

import { forkJoin } from 'rxjs';

const users$ = this.http.get('/api/users');
const posts$ = this.http.get('/api/posts');

forkJoin([users$, posts$]).subscribe(([users, posts]) => {
  console.log('Both loaded:', users, posts);
});

// Fetch details for a list of user IDs
from([1, 2, 3]).pipe(
  mergeMap(id => this.http.get(`/api/users/${id}`))
).subscribe(user => console.log(user));
